import json

# Load verbatim definitions
ixp_def = json.load(open('/tmp/ixp_receipts_def.json'))['Data']['Node']
scr_def = json.load(open('/tmp/script_def.json'))['Data']['Node']
end_def = json.load(open('/tmp/end_def.json'))['Data']['Node']

# IxP inputDefaults - modelName is null, use modelDisplayName
id_model = ixp_def['inputDefaults']['model'].copy()
if not id_model.get('modelName'):
    id_model['modelName'] = id_model['modelDisplayName']

ixp_node_type = ixp_def['nodeType']
ixp_type_version = ixp_def['version']
scr_type_version = scr_def['version']
end_type_version = end_def['version']

ixp_output_def = ixp_def['outputDefinition']['output']
ixp_error_def = ixp_def['outputDefinition']['error']

flow = {
  "id": "e7ae865b-6690-4ae4-983f-141af4f07845",
  "version": "1.8",
  "name": "ReceiptExtraction",
  "variables": {
    "globals": [
      {
        "id": "receiptImagePath",
        "name": "receiptImagePath",
        "type": "string",
        "direction": "in",
        "description": "Path to the receipt image file to extract"
      }
    ],
    "nodes": []
  },
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "6ad00e79-f0ec-405e-a7df-f7fd26f94b21",
        "isDefaultEntryPoint": True
      }
    },
    {
      "id": "extractReceiptFields",
      "type": ixp_node_type,
      "typeVersion": ixp_type_version,
      "display": {
        "label": "Extract Receipt Fields"
      },
      "inputs": {
        "model": id_model,
        "modelName": ixp_def['inputDefaults']['modelName'],
        "description": "",
        "projectName": ixp_def['inputDefaults']['projectName'],
        "versionTag": "",
        "folderKey": ixp_def['inputDefaults']['folderKey'],
        "folderName": ixp_def['inputDefaults']['folderName'],
        "fileRef": "=js:$vars.start.output.receiptImagePath",
        "pageRange": ""
      },
      "outputs": {
        "output": ixp_output_def,
        "error": ixp_error_def
      }
    },
    {
      "id": "parseReceiptData",
      "type": "core.action.script",
      "typeVersion": scr_type_version,
      "display": {
        "label": "Parse Receipt Data"
      },
      "inputs": {
        "language": "javascript",
        "script": (
          "const fields = ($vars.extractReceiptFields.output.ExtractionResult?.ResultsDocument?.Fields) || [];\n"
          "function getField(name) {\n"
          "  const f = fields.find(function(x) { return x.FieldName === name; });\n"
          "  return f && f.Values && f.Values.length > 0 ? f.Values[0] : null;\n"
          "}\n"
          "return {\n"
          "  merchant: getField('vendor_name') || getField('merchant') || getField('Merchant') || getField('VendorName') || null,\n"
          "  date: getField('date') || getField('Date') || getField('TransactionDate') || null,\n"
          "  total: getField('total') || getField('Total') || getField('TotalAmount') || getField('total_amount') || null\n"
          "};"
        )
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Extracted merchant, date, and total from the receipt",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end",
      "type": "core.control.end",
      "typeVersion": end_type_version,
      "display": {
        "label": "End"
      },
      "inputs": {},
      "outputs": {}
    }
  ],
  "edges": [
    {
      "id": "edge-start-to-extract",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "extractReceiptFields",
      "targetPort": "input"
    },
    {
      "id": "edge-extract-to-parse",
      "sourceNodeId": "extractReceiptFields",
      "sourcePort": "success",
      "targetNodeId": "parseReceiptData",
      "targetPort": "input"
    },
    {
      "id": "edge-parse-to-end",
      "sourceNodeId": "parseReceiptData",
      "sourcePort": "output",
      "targetNodeId": "end",
      "targetPort": "input"
    }
  ],
  "definitions": [
    {k: v for k, v in json.load(open('/tmp/ixp_receipts_def.json'))['Data']['Node'].items()},
    {k: v for k, v in json.load(open('/tmp/script_def.json'))['Data']['Node'].items()},
    {k: v for k, v in json.load(open('/tmp/end_def.json'))['Data']['Node'].items()},
    {k: v for k, v in json.loads(open('/work/output/artifacts/skill-flow-ixp-routing/receipts/ReceiptExtraction/ReceiptExtraction/ReceiptExtraction.flow').read())['definitions'][0].items()}
  ],
  "layout": {
    "nodes": {
      "start": {
        "position": { "x": 256, "y": 144 },
        "size": { "width": 96, "height": 96 },
        "collapsed": False
      },
      "extractReceiptFields": {
        "position": { "x": 0, "y": 0 },
        "size": { "width": 96, "height": 96 },
        "collapsed": False
      },
      "parseReceiptData": {
        "position": { "x": 0, "y": 0 },
        "size": { "width": 96, "height": 96 },
        "collapsed": False
      },
      "end": {
        "position": { "x": 0, "y": 0 },
        "size": { "width": 96, "height": 96 },
        "collapsed": False
      }
    }
  }
}

out = json.dumps(flow, indent=2)
open('/work/output/artifacts/skill-flow-ixp-routing/receipts/ReceiptExtraction/ReceiptExtraction/ReceiptExtraction.flow', 'w').write(out)
print('Written', len(out), 'bytes')
